import type { Argv, ArgumentsCamelCase } from 'yargs'
import { credentialProvider } from '../../auth'
import { logger } from '../../logger'
// biome-ignore lint/style/noRestrictedImports: TODO: can we replace with our path module?
import * as path from 'path'
import * as fs from 'fs'
import type { Telemetry } from '@servicenow/sdk-build-core'
import { createTelemetryClient } from '../../telemetry'
import { validateWorkingDir } from '../../util'
import { createLongRunningConnector, DEFAULT_TIMEOUT_SECONDS } from '../../util/longRunningConnector'
import { Project, Orchestrator } from '@servicenow/sdk-api'
import { NowConfig } from '@servicenow/sdk-build-core'
import { cwd } from 'process'

interface Arguments {
    directory: string
    source: string
    incremental: boolean
    timeout: number
}

export function builder(yargs: Argv) {
    return yargs
        .positional('directory', {
            describe: `Path to expand application`,
            type: 'string',
            demandOption: true,
        })
        .option('source', {
            describe: `Path to the directory that contains package.json configuration`,
            default: cwd(),
            type: 'string',
        })
        .option('incremental', {
            describe: 'Download application metadata from the instance in incremental mode',
            type: 'boolean',
            default: false,
        })
        .option('timeout', {
            describe:
                'Maximum time, in seconds, to wait for the instance to respond during the download before giving up',
            type: 'number',
            default: DEFAULT_TIMEOUT_SECONDS,
        })
}

export async function handler(args: ArgumentsCamelCase<Arguments>): Promise<void> {
    logger.info('Downloading application metadata from instance...')

    let telemetryClient: Telemetry | undefined
    try {
        const credential = await credentialProvider(args['auth'] as string)

        telemetryClient = createTelemetryClient(__dirname)

        logger.warn(
            'Updates to JavaScript modules are not included when downloading application metadata from your instance.'
        )
        const workingDir = validateWorkingDir(args.source)

        const config = NowConfig.parseFromDirectory(workingDir, fs, logger)

        const project = new Project({ config, fileSystem: fs, rootDir: workingDir, logger, telemetryClient })

        const connector = createLongRunningConnector(credential, args.timeout)
        const orchestrator = new Orchestrator(project, connector)

        const downloadPath = path.resolve(args.directory)

        const metaDownload = await orchestrator.download({ method: args.incremental ? 'incremental' : 'complete' })

        await orchestrator.unpack(metaDownload, downloadPath)

        logger.info(`Application downloaded and unpacked successfully to: ${downloadPath}`)
    } catch (error) {
        logger.error(error)
        process.exitCode = 1
    }
}
